/// Whether `c` joins the previous cell instead of taking a column.
pub fn is_spacing_mark(c: char) -> bool {
    let c = c as u32;
    c >= SPACING_MARKS[0].0
        && SPACING_MARKS
            .binary_search_by(|&(start, end)| {
                if end < c {
                    std::cmp::Ordering::Less
                } else if start > c {
                    std::cmp::Ordering::Greater
                } else {
                    std::cmp::Ordering::Equal
                }
            })
            .is_ok()
}
